"use client";

import { useId, useState } from "react";

import { cn } from "@/lib/utils";

import { STATUS_TEXT } from "../lib/status";
import { BlockFrame } from "../parts/block-frame";
import { StatFigure } from "../parts/stat-figure";
import { InvoiceList } from "./billing-overview/invoice-list";
import { UsageMeter } from "./shared/usage-meter";
import { ALLOWANCES, BUDGET, dayReaching, money, periodDay, PROJECTED, SPENT, START_RULES, USAGE_INVOICES, USAGE_PLANS } from "./usage-billing/data";
import { PlanCard } from "./usage-billing/plan-card";
import { SpendAlerts } from "./usage-billing/spend-alerts";
import { SpendChart } from "./usage-billing/spend-chart";

const MONEY: Intl.NumberFormatOptions = { maximumFractionDigits: 0 };

/**
 * Usage-based billing for one period: spend so far against the budget, a
 * projection to the period's end, the plan and its allowances, and the spend
 * alerts. Upgrading grows every allowance, so the bars shrink and their
 * warnings clear in place.
 */
export function UsageBilling({ className }: { className?: string }) {
  const [rules, setRules] = useState(START_RULES);
  const [upgraded, setUpgraded] = useState(false);
  const [confirming, setConfirming] = useState(false);
  const [hovered, setHovered] = useState<string | null>(null);
  const [announce, setAnnounce] = useState("");
  const titleId = useId();

  const spent = SPENT.at(-1) ?? 0;
  const projected = PROJECTED.at(-1) ?? 0;
  const plan = upgraded ? USAGE_PLANS.network : USAGE_PLANS.practice;
  const nextRule = rules.find((rule) => rule.amount > spent);
  const nextDay = nextRule ? dayReaching(nextRule.amount) : null;
  const sentence = nextRule
    ? nextDay === null
      ? `At this pace no alert fires before Nov 30. The next one is at ${money(nextRule.amount)}.`
      : `At this pace you reach the ${money(nextRule.amount)} alert around ${periodDay(nextDay)}.`
    : "Every alert amount has been passed this period.";

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-5 py-4">
        <div>
          <h2 id={titleId} className="text-base font-semibold">
            Usage and spend
          </h2>
          <p className="text-sm text-muted-foreground">Fernhill Physio Group, Nov 1 to Nov 30</p>
        </div>
      </header>

      <dl className="grid grid-cols-1 gap-px border-b border-border bg-border @md:grid-cols-3">
        <StatFigure label="Spent so far" roll={{ value: Math.round(spent), format: MONEY, prefix: "$" }}>
          Day 11 of 30
        </StatFigure>
        <StatFigure label="Projected for the period" roll={{ value: Math.round(projected), format: MONEY, prefix: "$" }}>
          <span className={cn(projected > BUDGET ? STATUS_TEXT.bad : STATUS_TEXT.good)}>
            {projected > BUDGET ? `${money(projected - BUDGET)} over budget` : "Within budget"}
          </span>
        </StatFigure>
        <StatFigure label="Budget" roll={{ value: BUDGET, format: MONEY, prefix: "$" }}>
          Resets Dec 1
        </StatFigure>
      </dl>

      <div className="grid @3xl:grid-cols-[1fr_19rem]">
        <section aria-label="Spend over the period" className="flex min-w-0 flex-col gap-3 p-5 @3xl:min-h-0">
          <p className="text-sm" aria-live="polite">
            {sentence}
          </p>
          <SpendChart rules={rules} budget={BUDGET} />
        </section>

        <aside aria-label="Plan and allowances" className="flex flex-col gap-5 border-t border-border p-5 @3xl:border-t-0 @3xl:border-l">
          <PlanCard
            upgraded={upgraded}
            confirming={confirming}
            onAsk={() => setConfirming(true)}
            onCancel={() => setConfirming(false)}
            onConfirm={() => {
              setUpgraded(true);
              setConfirming(false);
              setAnnounce(`Upgraded to the ${USAGE_PLANS.network.name} plan. Every allowance grew.`);
            }}
          />
          <div className="flex flex-col gap-4">
            {ALLOWANCES.map((item, order) => {
              const limit = plan.limits[item.key];
              const over = item.used - limit;
              return (
                <UsageMeter
                  key={item.key}
                  label={item.label}
                  used={item.used}
                  limit={limit}
                  format={item.format}
                  tone={item.tone}
                  order={order}
                  note={over > 0 ? `${item.format(over)} over. ${item.overage}.` : item.overage}
                  dimmed={hovered !== null && hovered !== item.key}
                  onHover={(on) => setHovered(on ? item.key : null)}
                />
              );
            })}
          </div>
        </aside>
      </div>

      <div className="grid gap-px border-t border-border bg-border @3xl:grid-cols-[1fr_19rem]">
        <section aria-labelledby={`${titleId}-alerts`} className="flex flex-col gap-3 bg-card p-5">
          <div>
            <h3 id={`${titleId}-alerts`} className="text-sm font-semibold">
              Spend alerts
            </h3>
            <p className="text-sm text-muted-foreground">We tell you when spend passes each amount.</p>
          </div>
          <SpendAlerts rules={rules} budget={BUDGET} onChange={setRules} />
        </section>
        <section aria-labelledby={`${titleId}-invoices`} className="flex flex-col gap-2 bg-card p-5">
          <h3 id={`${titleId}-invoices`} className="text-sm font-semibold">
            Past invoices
          </h3>
          <InvoiceList compact invoices={USAGE_INVOICES} onDownload={(invoice) => setAnnounce(`Invoice ${invoice.id} downloaded.`)} />
        </section>
      </div>
      <p role="status" className="sr-only">
        {announce}
      </p>
    </BlockFrame>
  );
}

/** The three states a figure or a row can be in. */
export type Status = "good" | "watch" | "bad";

/** The text colour for each state. Each one passes 4.5 to 1 on a card in both themes. */
export const STATUS_TEXT = {
  good: "text-marketing-green-ink",
  watch: "text-marketing-amber-ink",
  bad: "text-marketing-orange-ink",
} satisfies Record<Status, string>;

/** A tinted surface for each state, for a pill or a cell. Pair it with the matching text colour. */
export const STATUS_SURFACE = {
  good: "bg-marketing-green-surface",
  watch: "bg-marketing-amber-surface",
  bad: "bg-marketing-orange-surface",
} satisfies Record<Status, string>;

/** The word a screen reader and a label use for each state. Colour never carries a state alone. */
export const STATUS_WORD = {
  good: "Good",
  watch: "Watch",
  bad: "At risk",
} satisfies Record<Status, string>;

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

import type { ReactNode } from "react";

import { NumberTicker } from "@/components/motion/number-ticker";
import { cn } from "@/lib/utils";

/** A headline figure given as a number, so its digits roll when it changes. */
export interface StatFigureRoll {
  /** The number to show. Round it first when the figure is a whole number. */
  value: number;
  /** A module-level constant, never an inline object: the ticker memoises its formatter on it. */
  format: Intl.NumberFormatOptions;
  /** Text before the number with no space, such as a sign. */
  prefix?: string;
  /** Text after the number with no space, such as "%". */
  suffix?: string;
  /** A word after the number, with a space before it, such as "messages". */
  unit?: string;
}

/** Props for one headline figure. */
export interface StatFigureProps {
  label: string;
  /** The figure as ready text. Leave it out when `roll` is set. */
  value?: ReactNode;
  /** The figure as a number whose digits roll on change. It takes the place of `value`. */
  roll?: StatFigureRoll;
  /** A change figure or a short note under the value. */
  children?: ReactNode;
  className?: string;
}

/** One headline figure with its name and a note. Place it inside a `dl`. */
export function StatFigure({ label, value, roll, children, className }: StatFigureProps) {
  return (
    <div className={cn("flex min-w-0 flex-col gap-1 bg-card px-5 py-4", className)}>
      <dt className="truncate text-sm text-muted-foreground">{label}</dt>
      <dd className="text-2xl font-semibold tracking-tight tabular-nums">
        {roll ? (
          <>
            {roll.prefix}
            <NumberTicker value={roll.value} format={roll.format} />
            {roll.suffix}
            {roll.unit ? ` ${roll.unit}` : null}
          </>
        ) : (
          value
        )}
      </dd>
      {children ? <dd className="flex min-w-0 items-center gap-x-2 overflow-hidden text-xs whitespace-nowrap text-muted-foreground">{children}</dd> : null}
    </div>
  );
}

"use client";

import { useState } from "react";

import { CircleCheckIcon, DownloadIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { formatMoney } from "../../lib/format";
import { STATUS_TEXT } from "../../lib/status";
import type { Invoice } from "./data";

/** Props for the invoice list. */
export interface InvoiceListProps {
  invoices: Invoice[];
  onDownload: (invoice: Invoice) => void;
  /** Keeps the two-line layout at every width, for a narrow column. */
  compact?: boolean;
}

/**
 * Past invoices, newest first, each with its plan, amount, paid state and a
 * download. Hovering a row fades the others, so the eye stays on one.
 */
export function InvoiceList({ invoices, onDownload, compact = false }: InvoiceListProps) {
  const [hovered, setHovered] = useState<string | null>(null);
  return (
    <ul className="flex flex-col" onPointerLeave={() => setHovered(null)}>
      {invoices.map((invoice) => (
        <li
          key={invoice.id}
          onPointerEnter={() => setHovered(invoice.id)}
          className={cn(
            "relative isolate grid grid-cols-[1fr_auto_auto] items-center gap-x-3 gap-y-0.5 rounded-lg px-2 py-2.5 transition-opacity duration-150",
            compact ? undefined : "@lg:grid-cols-[8rem_1fr_6rem_5rem_auto] @lg:gap-x-4",
            hovered && hovered !== invoice.id ? "opacity-50" : "opacity-100",
          )}
        >
          <span aria-hidden="true" className={cn("absolute inset-0 -z-10 rounded-lg", hovered === invoice.id ? "bg-muted" : undefined)} />
          <span className="text-sm font-medium">{invoice.date}</span>
          <span className={cn("col-start-1 row-start-2 truncate text-xs text-muted-foreground", compact ? undefined : "@lg:col-auto @lg:row-auto @lg:text-sm")}>
            {invoice.plan}
          </span>
          <span className={cn("text-right text-sm tabular-nums", compact ? undefined : "@lg:col-auto")}>{formatMoney(invoice.amount)}</span>
          <span className={cn("col-start-2 row-start-2 inline-flex items-center justify-end gap-1 text-xs", compact ? undefined : "@lg:col-auto @lg:row-auto @lg:justify-start", STATUS_TEXT.good)}>
            <CircleCheckIcon aria-hidden="true" className="size-3.5" />
            Paid
          </span>
          <Button variant="ghost" size="icon" className={cn("col-start-3 row-span-2 row-start-1", compact ? undefined : "@lg:col-auto @lg:row-span-1 @lg:row-auto")} aria-label={`Download invoice ${invoice.id}`} onClick={() => onDownload(invoice)}>
            <DownloadIcon aria-hidden="true" className="size-4" />
          </Button>
        </li>
      ))}
    </ul>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

/** A warning triangle, from the chosen icon pack. */
export const AlertTriangleIcon = packIcon("alert-triangle");
/** An arrow that points down, from the chosen icon pack. */
export const ArrowDownIcon = packIcon("arrow-up", "rotate-180");
/** An arrow that points left, from the chosen icon pack. */
export const ArrowLeftIcon = packIcon("arrow-up", "-rotate-90");
/** An arrow that points up, from the chosen icon pack. */
export const ArrowUpIcon = packIcon("arrow-up");
/** A bell, from the chosen icon pack. */
export const BellIcon = packIcon("bell");
/** A calendar, from the chosen icon pack. */
export const CalendarIcon = packIcon("calendar");
/** A check mark, from the chosen icon pack. */
export const CheckIcon = packIcon("check");
/** A chevron that points down, from the chosen icon pack. */
export const ChevronDownIcon = packIcon("chevron-down");
/** A chevron that points right, from the chosen icon pack. */
export const ChevronRightIcon = packIcon("chevron-right");
/** A check mark in a circle, from the chosen icon pack. */
export const CircleCheckIcon = packIcon("circle-check");
/** A cross in a circle, from the chosen icon pack. */
export const CircleXIcon = packIcon("circle-x");
/** A download arrow, from the chosen icon pack. */
export const DownloadIcon = packIcon("download");
/** A globe, from the chosen icon pack. */
export const GlobeIcon = packIcon("globe");
/** An expand mark, from the chosen icon pack. */
export const MaximizeIcon = packIcon("expand");
/** A speech bubble, from the chosen icon pack. */
export const MessageIcon = packIcon("message");
/** A play mark, from the chosen icon pack. */
export const PlayerPlayFilledIcon = packIcon("play");
/** A plus, from the chosen icon pack. */
export const PlusIcon = packIcon("plus");
/** A refresh mark, from the chosen icon pack. */
export const RefreshIcon = packIcon("refresh");
/** Sparkles, from the chosen icon pack. */
export const SparklesIcon = packIcon("sparkles");
/** Two people, from the chosen icon pack. */
export const UsersIcon = packIcon("users");
/** A close mark, from the chosen icon pack. */
export const XIcon = packIcon("x");

/** Two arrows that cross, for swapping two things. */
export const ArrowsShuffleIcon = ownIcon(
  <>
    <path d="M2 4.5h2.2c1.2 0 2.3.6 3 1.6l1.6 3.8c.7 1 1.8 1.6 3 1.6H14" />
    <path d="M2 11.5h2.2c1 0 1.9-.4 2.6-1.1M9.2 5.6c.7-.7 1.6-1.1 2.6-1.1H14" />
    <path d="M12 2.5l2 2-2 2M12 9.5l2 2-2 2" />
  </>,
);

/** Six dots, for a handle a person drags. */
export const GripVerticalIcon = ownIcon(
  <path d="M6 3.5h.01M10 3.5h.01M6 8h.01M10 8h.01M6 12.5h.01M10 12.5h.01" strokeWidth="2" />,
);

/** Two bars, for pause. */
export const PlayerPauseFilledIcon = ownIcon(<path d="M5.5 3.5v9M10.5 3.5v9" strokeWidth="2.5" />);

/** A bin, for remove. */
export const TrashIcon = ownIcon(
  <>
    <path d="M2.5 4.5h11M6 4.5V3a.5.5 0 0 1 .5-.5h3A.5.5 0 0 1 10 3v1.5" />
    <path d="M4 4.5l.6 8a1 1 0 0 0 1 .9h4.8a1 1 0 0 0 1-.9l.6-8M6.75 7v4M9.25 7v4" />
  </>,
);

const WHOLE = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });
const ONE_PLACE = new Intl.NumberFormat("en-US", { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const COMPACT = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 });
const MONEY = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 });

/** A whole number with thousands separators. */
export const formatWhole = (value: number) => WHOLE.format(Math.round(value));

/** A number with one decimal place. */
export const formatOnePlace = (value: number) => ONE_PLACE.format(value);

/** A short number for an axis, such as 1.2K. */
export const formatCompact = (value: number) => COMPACT.format(value);

/** A dollar amount with no cents. */
export const formatMoney = (value: number) => MONEY.format(Math.round(value));

/** A percent with one decimal place and no sign. */
export const formatPercent = (value: number) => `${ONE_PLACE.format(Math.abs(value))}%`;

const DAY = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", timeZone: "UTC" });
const WEEKDAY = new Intl.DateTimeFormat("en-US", { weekday: "long", timeZone: "UTC" });

/** The sample data ends on this day, so every block shows the same dates on every render. */
export const SAMPLE_END = Date.UTC(2026, 9, 31);

/** The date `daysBeforeEnd` days before the last sample day. */
export const sampleDate = (daysBeforeEnd: number) => new Date(SAMPLE_END - daysBeforeEnd * 86_400_000);

/** A short date, such as Oct 31. */
export const formatDay = (date: Date) => DAY.format(date);

/** A weekday name, such as Tuesday. */
export const formatWeekday = (date: Date) => WEEKDAY.format(date);

import { formatWhole } from "../../lib/format";

/** The plans a clinic can be on. */
export type PlanId = "solo" | "clinic" | "group";

/** How often the plan is paid for. */
export type Period = "month" | "year";

/** One plan with its monthly price and limits. */
export interface Plan {
  id: PlanId;
  name: string;
  /** The price per month when paid monthly. A year costs ten months. */
  monthly: number;
  blurb: string;
  practitioners: number;
  texts: number;
  /** Storage in gigabytes. */
  storage: number;
}

/** The plans in price order. */
export const PLANS: Plan[] = [
  { id: "solo", name: "Solo", monthly: 29, blurb: "One practitioner, one room.", practitioners: 1, texts: 300, storage: 5 },
  { id: "clinic", name: "Clinic", monthly: 89, blurb: "A small team sharing rooms.", practitioners: 6, texts: 1500, storage: 50 },
  { id: "group", name: "Group", monthly: 189, blurb: "Several clinics under one roof.", practitioners: 20, texts: 5000, storage: 200 },
];

/** What a plan costs for one period. */
export const priceFor = (plan: Plan, period: Period) => (period === "month" ? plan.monthly : plan.monthly * 10);

/** This period's use of each limited resource. */
export const USAGE = { practitioners: 5, texts: 1312, storage: 18.4 };

/** The resources a plan limits, with how each figure reads. */
export const RESOURCES = [
  { key: "practitioners", label: "Practitioners", tone: "bg-chart-1", format: (value: number) => `${formatWhole(value)} seats` },
  { key: "texts", label: "Reminder texts", tone: "bg-chart-2", format: (value: number) => `${formatWhole(value)} texts` },
  { key: "storage", label: "Patient files", tone: "bg-chart-3", format: (value: number) => `${value % 1 === 0 ? formatWhole(value) : value.toFixed(1)} GB` },
] as const;

/** One past invoice. */
export interface Invoice {
  id: string;
  date: string;
  amount: number;
  plan: string;
}

/** The invoices, newest first. */
export const INVOICES: Invoice[] = [
  { id: "FH-2026-0011", date: "Nov 1, 2026", amount: 89, plan: "Clinic" },
  { id: "FH-2026-0010", date: "Oct 1, 2026", amount: 89, plan: "Clinic" },
  { id: "FH-2026-0009", date: "Sep 1, 2026", amount: 71, plan: "Clinic, part month" },
  { id: "FH-2026-0008", date: "Aug 1, 2026", amount: 29, plan: "Solo" },
];

/** The card on file. */
export const CARD = { brand: "Visa", last4: "4412", expiry: "08/28", holder: "Harbour Street Physio" };

/** The renewal date of the current period. */
export const RENEWS = "Dec 1, 2026";

"use client";

import type { CSSProperties } from "react";
import { AlertTriangleIcon } from "@/components/blocks/parts/icons";
import { cn } from "@/lib/utils";

import { STATUS_SURFACE, STATUS_TEXT } from "../../lib/status";
import { RollingText } from "../../parts/rolling-text";

/** Props for one usage bar against its limit. */
export interface UsageMeterProps {
  label: string;
  used: number;
  limit: number;
  /** Writes a figure with its unit, such as "1,240 texts". */
  format: (value: number) => string;
  /** The fill colour, such as `bg-chart-2`. */
  tone: string;
  /** Where the bar sits in a staggered fill, from 0. */
  order?: number;
  /** A short note under the bar, such as the overage price. */
  note?: string;
  /** Fades the meter when another meter is hovered. */
  dimmed?: boolean;
  onHover?: (hovered: boolean) => void;
}

const DELAYS = ["delay-0", "delay-100", "delay-200", "delay-300"];

/** The share of the limit at which a meter warns. */
export const NEAR_LIMIT = 0.8;

/**
 * One resource against its limit: the figures, a bar that fills with a short
 * stagger, and a flag once usage passes 80 percent. The flag uses a word and
 * an icon as well as colour, so it never relies on colour alone.
 */
export function UsageMeter({ label, used, limit, format, tone, order = 0, note, dimmed, onHover }: UsageMeterProps) {
  const share = limit > 0 ? used / limit : 0;
  const over = share > 1;
  const near = !over && share >= NEAR_LIMIT;
  const state = over ? "bad" : near ? "watch" : null;
  return (
    <div
      className={cn("flex flex-col gap-2 transition-opacity duration-200", dimmed ? "opacity-45" : "opacity-100")}
      onPointerEnter={() => onHover?.(true)}
      onPointerLeave={() => onHover?.(false)}
    >
      <div className="flex flex-wrap items-baseline justify-between gap-x-3 gap-y-1">
        <span className="text-sm font-medium">{label}</span>
        <span className="text-sm text-muted-foreground tabular-nums">
          <RollingText text={format(used)} className="text-foreground" /> of <RollingText text={format(limit)} />
        </span>
      </div>
      <div
        role="meter"
        aria-label={label}
        aria-valuemin={0}
        aria-valuemax={limit}
        aria-valuenow={Math.min(used, limit)}
        aria-valuetext={`${format(used)} of ${format(limit)}`}
        className="relative h-2 overflow-hidden rounded-full bg-muted"
      >
        <span
          className={cn(
            "absolute inset-y-0 left-0 w-(--fill) rounded-full motion-safe:transition-all motion-safe:duration-700 motion-safe:ease-out",
            DELAYS[order % DELAYS.length],
            over ? "bg-chart-5" : tone,
          )}
          // SAFETY: the object sets only CSS custom properties, which React passes to the element as they are.
          style={{ "--fill": `${Math.min(100, share * 100)}%` } as CSSProperties}
        />
      </div>
      <div className="flex min-h-5 flex-wrap items-center gap-2 text-xs text-muted-foreground">
        {state ? (
          <span className={cn("inline-flex items-center gap-1 rounded-full px-2 py-0.5 font-medium", STATUS_SURFACE[state], STATUS_TEXT[state])}>
            <AlertTriangleIcon aria-hidden="true" className="size-3" />
            {over ? "Over the limit" : "Near the limit"}
          </span>
        ) : null}
        {note ? <span>{note}</span> : null}
      </div>
    </div>
  );
}

import { NumberTicker } from "@/components/motion/number-ticker";
import { cn } from "@/lib/utils";

/** Props for a formatted figure whose digits roll. */
export interface RollingTextProps {
  /** A figure that is already formatted, such as "$3,577" or "8.2 min". */
  text: string;
  className?: string;
}

/**
 * Shows a formatted figure and rolls each digit to its new value when the
 * text changes, as a counter does. Signs, separators and units stay still.
 * Each glyph is keyed by its place from the right, so a digit keeps its
 * column when the figure grows. It is for text that already has another
 * spoken source: the rolling columns are hidden from screen readers.
 */
export function RollingText({ text, className }: RollingTextProps) {
  const glyphs = [...text];
  return (
    <span className={cn("inline-flex tabular-nums", className)}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true" className="inline-flex">
        {glyphs.map((glyph, index) => {
          const place = glyphs.length - 1 - index;
          return glyph >= "0" && glyph <= "9" ? (
            <NumberTicker key={place} value={Number(glyph)} />
          ) : (
            <span key={place} className="whitespace-pre">
              {glyph}
            </span>
          );
        })}
      </span>
    </span>
  );
}

import { formatMoney, formatWhole } from "../../lib/format";
import { seededRandom } from "../../lib/plot";
