/** The days in the billing period. */
export const PERIOD_DAYS = 30;

/** The days of the period that have passed. */
export const DAYS_PASSED = 11;

/** The budget for the period. */
export const BUDGET = 600;

/** Spend so far, added up day by day, for the days that have passed. */
export const SPENT: number[] = (() => {
  const random = seededRandom(41);
  let total = 0;
  return Array.from({ length: DAYS_PASSED }, (_, day) => {
    // Weekdays carry more visits, and so more reminder texts and video minutes.
    const weekday = (day + 6) % 7 < 5;
    total += (weekday ? 24 : 9) + random() * 8;
    return Math.round(total * 100) / 100;
  });
})();

/** The average spend per day so far. */
export const DAILY_PACE = (SPENT.at(-1) ?? 0) / DAYS_PASSED;

/** The whole period: the real days, then each later day projected at the pace so far. */
export const PROJECTED: number[] = Array.from({ length: PERIOD_DAYS }, (_, day) =>
  day < DAYS_PASSED ? (SPENT[day] ?? 0) : (SPENT.at(-1) ?? 0) + DAILY_PACE * (day - DAYS_PASSED + 1),
);

/** A date in the period, such as Nov 12, from a day index starting at 0. */
export const periodDay = (index: number) => `Nov ${index + 1}`;

/** The first projected day that reaches `amount`, or null when the period ends first. */
export function dayReaching(amount: number) {
  const index = PROJECTED.findIndex((value) => value >= amount);
  return index === -1 ? null : index;
}

