/**
 * Plot maths shared by the blocks. Every path is drawn in a 0 to 100 box, and
 * the SVG stretches it with `preserveAspectRatio="none"`, so a chart needs no
 * resize observer. Strokes keep their width through `vector-effect`.
 */

/** A repeatable random source, so sample data is the same on the server and in the browser. */
export function seededRandom(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state * 1664525 + 1013904223) >>> 0;
    return state / 4294967296;
  };
}

// Monday to Sunday: a working week that tails off, then a quiet weekend.
const WEEKDAY_LIFT = [0.35, 0.5, 0.2, 0.1, -0.05, -0.75, -1];

/** Sample data that moves from `start` to `end` with a working-week rhythm and some noise. */
export function makeSeries(seed: number, length: number, start: number, end: number, noise: number): number[] {
  const random = seededRandom(seed);
  return Array.from({ length }, (_, index) => {
    const progress = length === 1 ? 1 : index / (length - 1);
    const trend = start + (end - start) * progress;
    const week = (WEEKDAY_LIFT[index % 7] ?? 0) * noise * 0.6;
    return Math.max(0, trend + week + (random() - 0.5) * noise * 0.7);
  });
}

/** The lowest and highest value across several series, padded so a line never touches the frame. */
export function paddedExtent(series: number[][], padding = 0.12): [number, number] {
  const values = series.flat();
  const low = Math.min(...values);
  const high = Math.max(...values);
  const span = high - low || 1;
  return [Math.max(0, low - span * padding), high + span * padding];
}

/** Where a value sits in the box, from 0 at the top to 100 at the bottom. */
export function toY(value: number, [low, high]: [number, number]): number {
  return 100 - ((value - low) / (high - low || 1)) * 100;
}

/** Where a point sits across the box, from 0 to 100. */
export function toX(index: number, length: number): number {
  return length <= 1 ? 50 : (index / (length - 1)) * 100;
}

/** The value at a fractional position along a series, read off the straight line between its neighbours. */
function valueAt(values: number[], position: number): number {
  const left = Math.floor(position);
  const right = Math.min(values.length - 1, left + 1);
  const from = values[left] ?? 0;
  const to = values[right] ?? from;
  return from + (to - from) * (position - left);
}

/**
 * A line through `values` with a fixed number of segments. Two paths with the
 * same segment count can morph into each other, whatever their point counts.
 */
export function linePath(values: number[], extent: [number, number], samples = 60): string {
  if (values.length === 0) return "";
  const parts: string[] = [];
  for (let step = 0; step <= samples; step += 1) {
    const position = (step / samples) * (values.length - 1);
    const x = (step / samples) * 100;
    const y = toY(valueAt(values, position), extent);
    parts.push(`${step === 0 ? "M" : "L"}${x.toFixed(2)} ${y.toFixed(2)}`);
  }
  return parts.join(" ");
}

/** The same line, closed down to the bottom edge, for a filled area. */
export function areaPath(values: number[], extent: [number, number], samples = 60): string {
  const line = linePath(values, extent, samples);
  return line ? `${line} L100 100 L0 100 Z` : "";
}

/** Round axis values between the low and high of the plot. */
export function axisTicks([low, high]: [number, number], count = 4): number[] {
  return Array.from({ length: count }, (_, index) => low + ((high - low) * index) / (count - 1));
}

/** The percent change from `before` to `after`, or 0 when there is nothing to compare against. */
export function percentChange(before: number, after: number): number {
  return before === 0 ? 0 : ((after - before) / before) * 100;
}

/** The sum of a series. */
export function sum(values: number[]): number {
  return values.reduce((total, value) => total + value, 0);
}

/** The mean of a series. */
export function mean(values: number[]): number {
  return values.length === 0 ? 0 : sum(values) / values.length;
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useRef } from "react";

import { NumberTicker } from "@/components/motion/number-ticker";
import { Button } from "@/components/ui/button";

import { formatWhole } from "../../lib/format";
import { RiseText } from "../shared/rise-text";
import { SpringHeight } from "../shared/spring-height";
import { ALLOWANCES, USAGE_PLANS } from "./data";

/** Props for the plan card. */
export interface PlanCardProps {
  upgraded: boolean;
  confirming: boolean;
  onAsk: () => void;
  onCancel: () => void;
  onConfirm: () => void;
}

const WHOLE: Intl.NumberFormatOptions = { maximumFractionDigits: 0 };

/**
 * The usage plan with its price and included allowances. Upgrade turns into
 * a small confirm sheet in the same place, naming the new price and limits;
 * focus moves to Confirm and returns to the card's button on Cancel.
 */
export function PlanCard({ upgraded, confirming, onAsk, onCancel, onConfirm }: PlanCardProps) {
  const reduceMotion = useReducedMotion();
  // Set on Cancel, so the Upgrade button takes focus back once it has mounted again.
  const returning = useRef(false);
  const cancel = () => {
    returning.current = true;
    onCancel();
  };
  const plan = upgraded ? USAGE_PLANS.network : USAGE_PLANS.practice;
  const next = USAGE_PLANS.network;
  const fade = reduceMotion ? { duration: 0 } : { duration: 0.16 };

  return (
    <div
      className="flex flex-col gap-3 rounded-xl border border-border p-4"
      onKeyDown={(event) => {
        if (event.key === "Escape" && confirming) {
          event.preventDefault();
          cancel();
        }
      }}
    >
      <div className="flex items-baseline justify-between gap-3">
        <h3 className="text-sm font-semibold">
          <RiseText text={`${plan.name} plan`} />
        </h3>
        <p className="text-sm tabular-nums">
          $<NumberTicker value={plan.price} format={WHOLE} className="font-semibold" />
          <span className="text-muted-foreground"> a month</span>
        </p>
      </div>
      <ul className="flex flex-col gap-1 text-sm text-muted-foreground">
        {ALLOWANCES.map((item) => (
          <li key={item.key} className="flex justify-between gap-3">
            <span>{item.label}</span>
            <span className="text-foreground tabular-nums">{item.format(plan.limits[item.key])}</span>
          </li>
        ))}
      </ul>
      <SpringHeight>
        <AnimatePresence mode="wait" initial={false}>
          {upgraded ? (
            <motion.p key="done" initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={fade} className="text-sm text-muted-foreground">
              You are on the largest usage plan.
            </motion.p>
          ) : confirming ? (
            <motion.div
              key="confirm"
              role="group"
              aria-label="Confirm upgrade"
              initial={reduceMotion ? false : { opacity: 0, scale: 0.96 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0 }}
              transition={fade}
              className="flex flex-col gap-3 rounded-lg bg-muted p-3"
            >
              <p className="text-sm">
                Move to {next.name} for ${formatWhole(next.price)} a month? Every allowance grows, and today you pay the difference for the days left.
              </p>
              <div className="flex justify-end gap-2">
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={cancel}
                >
                  Cancel
                </Button>
                <Button size="sm" autoFocus onClick={onConfirm}>
                  Confirm upgrade
                </Button>
              </div>
            </motion.div>
          ) : (
            <motion.div key="ask" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} transition={fade}>
              <Button
                ref={(node) => {
                  if (node && returning.current) {
                    returning.current = false;
                    node.focus();
                  }
                }}
                className="w-full"
                onClick={onAsk}
              >
                Upgrade to {next.name}
              </Button>
            </motion.div>
          )}
        </AnimatePresence>
      </SpringHeight>
    </div>
  );
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";

import { cn } from "@/lib/utils";

/** Props for a line of copy that rises into place when it changes. */
export interface RiseTextProps {
  text: string;
  className?: string;
}

/**
 * Shows one line of copy. When the text changes, the new line rises into
 * place while the old one lifts away. Under reduced motion it swaps at once.
 */
export function RiseText({ text, className }: RiseTextProps) {
  const reduceMotion = useReducedMotion();
  return (
    <span className={cn("relative inline-grid overflow-hidden", className)}>
      <AnimatePresence initial={false} mode="popLayout">
        <motion.span
          key={text}
          initial={reduceMotion ? false : { y: "100%", opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          exit={reduceMotion ? { opacity: 0, transition: { duration: 0 } } : { y: "-100%", opacity: 0 }}
          transition={{ type: "spring", stiffness: 420, damping: 38 }}
          className="col-start-1 row-start-1"
        >
          {text}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";
import { type ReactNode, useEffect, useRef, useState } from "react";

/** Props for a box whose height follows its content on a spring. */
export interface SpringHeightProps {
  children: ReactNode;
  className?: string;
}

/**
 * Measures its content and springs its own height to match, with no bounce,
 * so whatever sits under it glides instead of jumping. Under reduced motion
 * the height changes at once.
 */
export function SpringHeight({ children, className }: SpringHeightProps) {
  const innerRef = useRef<HTMLDivElement>(null);
  const [height, setHeight] = useState<number | "auto">("auto");
  const reduceMotion = useReducedMotion();

  useEffect(() => {
    const inner = innerRef.current;
    if (!inner) return;
    const observer = new ResizeObserver(([entry]) => {
      if (entry) setHeight(entry.borderBoxSize[0]?.blockSize ?? entry.contentRect.height);
    });
    observer.observe(inner);
    return () => observer.disconnect();
  }, []);

  return (
    <motion.div
      initial={false}
      animate={{ height }}
      transition={reduceMotion ? { duration: 0 } : { type: "spring", stiffness: 360, damping: 38 }}
      className="overflow-hidden"
    >
      <div ref={innerRef} className={className}>
        {children}
      </div>
    </motion.div>
  );
}

"use client";

import { useId, useState } from "react";

import { PlusIcon, TrashIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Toggle } from "@/components/ui/toggle";

import { ChatIcon, MailIcon, TextIcon } from "../icons";
import { SpringHeight } from "../shared/spring-height";
import {
  type AlertRule,
  type Channel,
  dayReaching,
  money,
  periodDay,
} from "./data";

/** Props for the spend alert rules. */
export interface SpendAlertsProps {
  rules: AlertRule[];
  budget: number;
  onChange: (rules: AlertRule[]) => void;
}

const CHANNELS = [
  { id: "email", label: "Email", Icon: MailIcon },
  { id: "chat", label: "Team chat", Icon: ChatIcon },
  { id: "text", label: "Text", Icon: TextIcon },
] as const;

/** The line under a rule: its share of the budget and the day the projection reaches it. */
function forecastLine(amount: number, budget: number) {
  if (!(amount > 0)) return "Enter an amount above $0.";
  const day = dayReaching(amount);
  const share = `${Math.round((amount / budget) * 100)}% of the budget`;
  return day === null
    ? `${share}. Not reached this period at the current pace.`
    : `${share}. Reached around ${periodDay(day)} at the current pace.`;
}

/**
 * The spend alerts, one row each: an amount, the channels it goes to, and a
 * line saying when the projection reaches it. Typing an amount updates that
 * line at once; Enter or leaving the field commits it, and the chart's alert
 * line moves to match. The list glides to its new height as rows change.
 */
export function SpendAlerts({ rules, budget, onChange }: SpendAlertsProps) {
  const [drafts, setDrafts] = useState<Record<string, string>>({});
  const baseId = useId();

  const commit = (id: string) => {
    const draft = drafts[id];
    if (draft === undefined) return;
    const amount = Math.round(Number(draft.replace(/[^\d.]/g, "")));
    if (amount > 0)
      onChange(
        rules
          .map((rule) => (rule.id === id ? { ...rule, amount } : rule))
          .sort((a, b) => a.amount - b.amount),
      );
    setDrafts(({ [id]: _, ...rest }) => rest);
  };

  const toggle = (id: string, channel: Channel, on: boolean) =>
    onChange(
      rules.map((rule) =>
        rule.id === id
          ? {
              ...rule,
              channels: on
                ? [...rule.channels, channel]
                : rule.channels.filter((item) => item !== channel),
            }
          : rule,
      ),
    );

  const add = () => {
    const highest = rules.at(-1)?.amount ?? 0;
    onChange([
      ...rules,
      { id: `rule-${Date.now()}`, amount: highest + 100, channels: ["email"] },
    ]);
  };

  return (
    <div className="flex flex-col gap-3">
      <SpringHeight>
        <ul className="flex flex-col gap-4">
          {rules.map((rule) => {
            const inputId = `${baseId}-${rule.id}`;
            const draft = drafts[rule.id];
            const shown = draft ?? String(rule.amount);
            return (
              <li key={rule.id} className="flex flex-col gap-2">
                <div className="flex flex-wrap items-center gap-2">
                  <label htmlFor={inputId} className="sr-only">
                    Alert amount
                  </label>
                  <div className="flex items-center gap-1.5">
                    <span
                      aria-hidden="true"
                      className="text-sm text-muted-foreground"
                    >
                      $
                    </span>
                    <Input
                      id={inputId}
                      inputMode="numeric"
                      value={shown}
                      aria-describedby={`${inputId}-hint`}
                      onChange={(event) =>
                        setDrafts((current) => ({
                          ...current,
                          [rule.id]: event.target.value,
                        }))
                      }
                      onBlur={() => commit(rule.id)}
                      onKeyDown={(event) =>
                        event.key === "Enter" && !event.nativeEvent.isComposing && event.keyCode !== 229
                          ? commit(rule.id)
                          : undefined
                      }
                      className="w-24"
                    />
                  </div>
                  <div
                    role="group"
                    aria-label={`Send the ${money(rule.amount)} alert to`}
                    className="flex flex-wrap gap-1"
                  >
                    {CHANNELS.map(({ id, label, Icon }) => (
                      <Toggle
                        key={id}
                        size="sm"
                        variant="outline"
                        pressed={rule.channels.includes(id)}
                        onPressedChange={(on) => toggle(rule.id, id, on)}
                      >
                        <Icon aria-hidden="true" className="size-3.5" />
                        {label}
                      </Toggle>
                    ))}
                  </div>
                  <Button
                    variant="ghost"
                    size="icon"
                    className="ml-auto"
                    aria-label={`Remove the ${money(rule.amount)} alert`}
                    onClick={() =>
                      onChange(rules.filter((item) => item.id !== rule.id))
                    }
                  >
                    <TrashIcon aria-hidden="true" className="size-4" />
                  </Button>
                </div>
                <p
                  id={`${inputId}-hint`}
                  className="text-xs text-muted-foreground"
                >
                  {forecastLine(Number(shown.replace(/[^\d.]/g, "")), budget)}
                </p>
              </li>
            );
          })}
        </ul>
      </SpringHeight>
      <Button
        variant="outline"
        size="sm"
        className="self-start"
        onClick={add}
        disabled={rules.length >= 5}
      >
        <PlusIcon aria-hidden="true" className="size-4" />
        Add an alert
      </Button>
    </div>
  );
}

