"use client";

import { motion, useReducedMotion } from "motion/react";
import { type CSSProperties, useId } from "react";

import { cn } from "@/lib/utils";

import { niceScale } from "../../lib/nice-scale";
import { linePath, toX, toY } from "../../lib/plot";
import { usePointCursor } from "../../lib/use-point-cursor";
import { PointTip } from "../../parts/point-tip";
import { type AlertRule, DAYS_PASSED, money, PERIOD_DAYS, periodDay, PROJECTED, SPENT } from "./data";

/** Props for the spend chart. */
export interface SpendChartProps {
  rules: AlertRule[];
  budget: number;
}

const RULE_TONES = ["stroke-chart-3", "stroke-chart-4", "stroke-chart-5"];
const RULE_TEXT = ["text-chart-3", "text-chart-4", "text-chart-5"];

/**
 * Spend so far as a solid line that continues as a dotted projection to the
 * end of the period, with a dashed line for each alert amount. The line draws
 * in once; the projection and alert lines follow. Arrows move the cursor a
 * day, and the readout under it speaks each day.
 */
export function SpendChart({ rules, budget }: SpendChartProps) {
  const cursor = usePointCursor(PERIOD_DAYS);
  const reduceMotion = useReducedMotion();
  const top = Math.max(budget, ...rules.map((rule) => rule.amount), PROJECTED.at(-1) ?? 0);
  const scale = niceScale(0, top * 1.05, 4);
  const extent: [number, number] = [scale.low, scale.high];
  const lastReal = DAYS_PASSED - 1;
  // Each path spans the full box, then a group transform squeezes it onto its own days.
  const realPath = linePath(SPENT, extent, 40);
  const projected = PROJECTED.slice(lastReal);
  const { index } = cursor;
  const value = index === null ? null : (PROJECTED[index] ?? 0);
  const future = index !== null && index > lastReal;

  const describe = (day: number) =>
    `${periodDay(day)}: ${money(PROJECTED[day] ?? 0)} ${day > lastReal ? "projected" : "spent so far"}.`;

  const clipId = useId();

  return (
    <div className="flex min-h-56 flex-1 flex-col gap-2">
      <p aria-live="polite" className="sr-only">
        {index === null ? "" : describe(index)}
      </p>
      <div className="flex flex-1 gap-3">
        <div aria-hidden="true" className="mb-6 flex w-10 shrink-0 flex-col-reverse justify-between text-right text-xs tabular-nums text-muted-foreground">
          {scale.ticks.map((tick) => (
            <span key={tick} className="-my-2 leading-4">
              {money(tick)}
            </span>
          ))}
        </div>
        <div className="flex min-w-0 flex-1 flex-col">
          <div
            {...cursor.plotProps}
            role="application"
            aria-roledescription="chart"
            aria-label="Spend this period with the projection to Nov 30. Use the arrow keys to read each day."
            className="relative min-h-56 flex-1 cursor-crosshair rounded-md outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-4 focus-visible:ring-offset-card"
          >
            <div aria-hidden="true" className="absolute inset-0 flex flex-col justify-between">
              {scale.ticks.map((tick) => (
                <span key={tick} className="h-px w-full bg-border" />
              ))}
            </div>
            <svg aria-hidden="true" viewBox="0 0 100 100" preserveAspectRatio="none" className="absolute inset-0 size-full overflow-visible">
              <defs>
                {/* The line draws in left to right by growing this clip once. */}
                <clipPath id={clipId}>
                  <motion.rect
                    x="-5"
                    y="-10"
                    height="120"
                    initial={{ width: reduceMotion ? 110 : 0 }}
                    animate={{ width: 110 }}
                    transition={reduceMotion ? { duration: 0 } : { duration: 0.9, ease: "easeOut" }}
                  />
                </clipPath>
              </defs>
              <g clipPath={`url(#${clipId})`} transform={`scale(${(lastReal / (PERIOD_DAYS - 1)).toFixed(4)} 1)`}>
                <path
                  d={realPath}
                  fill="none"
                  strokeWidth="2.25"
                  strokeLinejoin="round"
                  vectorEffect="non-scaling-stroke"
                  className="stroke-chart-1"
                />
              </g>
              <g transform={`translate(${toX(lastReal, PERIOD_DAYS).toFixed(3)} 0) scale(${((PERIOD_DAYS - 1 - lastReal) / (PERIOD_DAYS - 1)).toFixed(4)} 1)`}>
                <motion.path
                  d={linePath(projected, extent, 20)}
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  transition={reduceMotion ? { duration: 0 } : { duration: 0.4, delay: 0.9 }}
                  fill="none"
                  strokeWidth="2"
                  strokeDasharray="1 5"
                  strokeLinecap="round"
                  vectorEffect="non-scaling-stroke"
                  className="stroke-chart-1"
                />
              </g>
              {rules.map((rule, position) => (
                <motion.line
                  key={rule.id}
                  x1="0"
                  x2="100"
                  initial={{ opacity: 0, y1: toY(rule.amount, extent), y2: toY(rule.amount, extent) }}
                  animate={{ opacity: 1, y1: toY(rule.amount, extent), y2: toY(rule.amount, extent) }}
                  transition={reduceMotion ? { duration: 0 } : { opacity: { duration: 0.3, delay: 1.2 + position * 0.08 }, default: { type: "spring", stiffness: 300, damping: 34 } }}
                  strokeWidth="1.25"
                  strokeDasharray="4 4"
                  vectorEffect="non-scaling-stroke"
                  className={RULE_TONES[position % RULE_TONES.length]}
                />
              ))}
            </svg>
            {rules.map((rule, position) => (
              <span
                key={rule.id}
                aria-hidden="true"
                className={cn("pointer-events-none absolute top-(--at) right-0 -translate-y-full pb-0.5 text-xs font-medium tabular-nums", RULE_TEXT[position % RULE_TEXT.length])}
                // SAFETY: the object sets only CSS custom properties, which React passes to the element as they are.
                style={{ "--at": `${toY(rule.amount, extent)}%` } as CSSProperties}
              >
                {money(rule.amount)}
              </span>
            ))}
            {index !== null && value !== null ? (
              <>
                <div
                  aria-hidden="true"
                  className="pointer-events-none absolute inset-y-0 left-(--at)"
                  // SAFETY: the object sets only CSS custom properties, which React passes to the element as they are.
                  style={{ "--at": `${toX(index, PERIOD_DAYS)}%` } as CSSProperties}
                >
                  <span className="absolute inset-y-0 -left-px w-px bg-foreground/30" />
                  <span
                    className={cn("absolute top-(--at) -left-2 size-4 -translate-y-1/2 rounded-full border-2 border-chart-1 shadow-sm", future ? "border-dashed bg-card" : "bg-card")}
                    // SAFETY: the object sets only CSS custom properties, which React passes to the element as they are.
                    style={{ "--at": `${toY(value, extent)}%` } as CSSProperties}
                  />
                </div>
                <PointTip
                  x={toX(index, PERIOD_DAYS)}
                  y={toY(value, extent)}
                  title={periodDay(index)}
                  rows={[{ label: future ? "Projected" : "Spent so far", value: money(value), marker: "bg-chart-1", dashed: future }]}
                  note={`${Math.round((value / budget) * 100)}% of the ${money(budget)} budget`}
                />
              </>
            ) : null}
          </div>
          <div aria-hidden="true" className="mt-2 flex justify-between text-xs text-muted-foreground">
            <span>{periodDay(0)}</span>
            <span>Today, {periodDay(lastReal)}</span>
            <span>{periodDay(PERIOD_DAYS - 1)}</span>
          </div>
        </div>
      </div>
    </div>
  );
}

/** An axis that starts and ends on round values, with a tick at every step between. */
export interface NiceScale {
  low: number;
  high: number;
  step: number;
  ticks: number[];
}

/** The nearest round step at or above `raw`: 1, 2, 2.5 or 5 times a power of ten. */
export function niceStep(raw: number): number {
  if (!(raw > 0)) return 1;
  const power = 10 ** Math.floor(Math.log10(raw));
  const factor = raw / power;
  const round = factor <= 1 ? 1 : factor <= 2 ? 2 : factor <= 2.5 ? 2.5 : factor <= 5 ? 5 : 10;
  return round * power;
}

/** A round axis that holds `low` to `high` in about `count` steps. */
export function niceScale(low: number, high: number, count = 4): NiceScale {
  const step = niceStep((high - low || 1) / count);
  const first = Math.floor(low / step);
  const last = Math.max(first + 1, Math.ceil(high / step));
  const ticks = Array.from({ length: last - first + 1 }, (_, index) => (first + index) * step);
  return { low: first * step, high: last * step, step, ticks };
}

"use client";

import { type KeyboardEvent, type PointerEvent, useCallback, useState } from "react";

/** What a chart needs to let a person inspect one point with a pointer or the keyboard. */
export interface PointCursor {
  /** The inspected point, or null when nothing is inspected. */
  index: number | null;
  setIndex: (index: number | null) => void;
  /** Spread onto the focusable plot. Arrows step, Page keys jump, Home and End go to the ends, Escape clears. */
  plotProps: {
    tabIndex: 0;
    onKeyDown: (event: KeyboardEvent<HTMLElement>) => void;
    /** A tap or a press inspects the point under it, so a touch screen needs no hover. */
    onPointerDown: (event: PointerEvent<HTMLElement>) => void;
    onPointerMove: (event: PointerEvent<HTMLElement>) => void;
    onPointerLeave: (event: PointerEvent<HTMLElement>) => void;
    /** A finger can scrub across the plot while the page still scrolls up and down. */
    style: { touchAction: "pan-y" };
    onBlur: () => void;
  };
}

/**
 * Tracks the inspected point of a plot with `length` points. `pageStep` is how
 * far the Page keys and Shift with an arrow jump.
 */
export function usePointCursor(length: number, pageStep = 7): PointCursor {
  const [raw, setIndex] = useState<number | null>(null);
  // A shorter range can leave the cursor past the end, so clamp on read.
  const index = raw === null ? null : Math.min(raw, length - 1);

  const onKeyDown = useCallback(
    (event: KeyboardEvent<HTMLElement>) => {
      const last = length - 1;
      const current = index ?? last;
      const big = event.shiftKey ? pageStep : 1;
      let next: number | null;
      if (event.key === "ArrowLeft") next = index === null ? last : Math.max(0, current - big);
      else if (event.key === "ArrowRight") next = index === null ? last : Math.min(last, current + big);
      else if (event.key === "PageUp") next = Math.max(0, current - pageStep);
      else if (event.key === "PageDown") next = Math.min(last, current + pageStep);
      else if (event.key === "Home") next = 0;
      else if (event.key === "End") next = last;
      else if (event.key === "Escape" && index !== null) next = null;
      else return;
      event.preventDefault();
      setIndex(next);
    },
    [index, length, pageStep],
  );

  const onPointerMove = useCallback(
    (event: PointerEvent<HTMLElement>) => {
      const box = event.currentTarget.getBoundingClientRect();
      if (box.width === 0) return;
      const ratio = Math.min(1, Math.max(0, (event.clientX - box.left) / box.width));
      setIndex(Math.round(ratio * (length - 1)));
    },
    [length],
  );

  const clear = useCallback(() => setIndex(null), []);

  // A finger leaves the plot the moment it lifts. Clearing then would hide the point a tap just chose,
  // so only a mouse clears on the way out. A tapped point stays until the plot loses focus.
  const onPointerLeave = useCallback((event: PointerEvent<HTMLElement>) => {
    if (event.pointerType === "mouse") setIndex(null);
  }, []);

  return {
    index,
    setIndex,
    plotProps: {
      tabIndex: 0,
      onKeyDown,
      onPointerDown: onPointerMove,
      onPointerMove,
      onPointerLeave,
      onBlur: clear,
      style: { touchAction: "pan-y" },
    },
  };
}

import { cn } from "@/lib/utils";

import type { VarStyle } from "@/components/blocks/lib/css-vars";
import { RollingText } from "./rolling-text";

/** One line of a point's details. */
export interface PointTipRow {
  label: string;
  value: string;
  /** A class that colours the row's marker, such as `bg-chart-1`. Omit for a row with no series. */
  marker?: string;
  /** Draws the marker as a dashed line, for an earlier period. */
  dashed?: boolean;
}

/** Props for the card that shows one point's details. */
export interface PointTipProps {
  /** Where the point sits in its plot, from 0 to 100 on each axis, measured from the top left. */
  x: number;
  y: number;
  title: string;
  rows: PointTipRow[];
  /** A closing line, such as the difference between two rows. */
  note?: string;
  className?: string;
}

/**
 * A small card beside an inspected point. It sits on the side of the point
 * with more room and stays inside the plot. In a plot narrower than the card
 * and the point together, it may cover the point rather than be cut off.
 * The digits of each value roll to the next point's figure as the point changes.
 * The card blurs what is behind it, so a design system with a see-through popover stays legible.
 * It is decorative for screen readers: the plot's live readout says the same.
 */
export function PointTip({ x, y, title, rows, note, className }: PointTipProps) {
  const onLeft = x > 55;
  return (
    <div
      aria-hidden="true"
      className={cn("pointer-events-none absolute top-(--y) z-10", onLeft ? "right-(--side)" : "left-(--side)", className)}
      style={
        // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
        {
          // The card hangs one rem from the point, but never past the plot's edge: 14rem is its widest.
          "--side": `min(calc(${onLeft ? 100 - x : x}% + 1rem), calc(100% - 14rem))`,
          "--y": `${Math.min(78, Math.max(22, y))}%`,
        } as VarStyle
      }
    >
      <div
        className={cn(
          "flex w-max max-w-56 -translate-y-1/2 flex-col gap-1.5 rounded-xl border border-border bg-popover px-3 py-2 text-popover-foreground shadow-lg backdrop-blur-md",
        )}
      >
        <span className="text-xs text-muted-foreground">{title}</span>
        {rows.map((row) => (
          <span key={row.label} className="flex items-center justify-between gap-6 text-sm">
            <span className="flex items-center gap-2 text-muted-foreground">
              {row.marker ? (
                <span className={cn("h-0.5 w-3 rounded-full", row.dashed ? "border-t border-dashed border-current" : row.marker)} />
              ) : null}
              {row.label}
            </span>
            <RollingText text={row.value} className="font-medium" />
          </span>
        ))}
        {note ? <span className="border-t border-border pt-1.5 text-xs text-muted-foreground">{note}</span> : null}
      </div>
    </div>
  );
}

import type { CSSProperties } from "react";

/**
 * An inline style made only of custom properties, for values known at render
 * such as a point's place in a plot. Classes read them, as `left-(--x)` does.
 */
export type VarStyle = CSSProperties & { [name: `--${string}`]: string | number };
